  "inlineSchema": "// FITVERSE — Prisma Schema\n// Phase 1: User + RefreshToken (authentication). Remaining entities\n// (Profile, Workout, Nutrition, Progress, Gamification, Social, AI, etc.)\n// are added in later phases per the Database Design & ER Diagram Spec.\n\ngenerator client {\n  provider     = \"prisma-client\"\n  output       = \"../src/generated/prisma\"\n  moduleFormat = \"cjs\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum Role {\n  USER\n  ADMIN\n}\n\nmodel User {\n  id           String   @id @default(cuid())\n  email        String   @unique\n  passwordHash String\n  role         Role     @default(USER)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  refreshTokens    RefreshToken[]\n  profile          Profile?\n  workouts         Workout[]\n  nutritionEntries NutritionEntry[]\n  progressEntries  Progress[]\n}\n\n// Refresh tokens are stored hashed (never the raw token) so a logout or\n// rotation can actually revoke server-side, rather than just trusting the\n// client to discard it.\nmodel RefreshToken {\n  id        String    @id @default(cuid())\n  tokenHash String    @unique\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  expiresAt DateTime\n  revokedAt DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId])\n}\n\nenum FitnessGoal {\n  MUSCLE_GAIN\n  FAT_LOSS\n  WEIGHT_MAINTENANCE\n  STRENGTH\n  ENDURANCE\n  GENERAL_FITNESS\n}\n\nenum ActivityLevel {\n  SEDENTARY\n  LIGHTLY_ACTIVE\n  MODERATELY_ACTIVE\n  VERY_ACTIVE\n  EXTREMELY_ACTIVE\n}\n\nenum DietaryPreference {\n  NONE\n  VEGETARIAN\n  VEGAN\n  PESCATARIAN\n  KETO\n  PALEO\n  GLUTEN_FREE\n  HALAL\n  KOSHER\n}\n\nenum WorkoutType {\n  STRENGTH_TRAINING\n  CARDIO\n  HIIT\n  YOGA\n  PILATES\n  CROSSFIT\n  CALISTHENICS\n  MIXED\n}\n\n// 1:1 with User. All fitness fields are nullable — profile setup is\n// progressive, and PUT /profiles/me does a true full-replace upsert (a\n// field omitted from the request clears to null), so partial-vs-complete\n// is entirely a frontend concern, not a backend one.\nmodel Profile {\n  id                   String             @id @default(cuid())\n  userId               String             @unique\n  user                 User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  age                  Int?\n  heightCm             Float?\n  weightKg             Float?\n  targetWeightKg       Float?\n  fitnessGoal          FitnessGoal?\n  activityLevel        ActivityLevel?\n  workoutFrequency     Int?\n  availableEquipment   String[]           @default([])\n  dietaryPreference    DietaryPreference?\n  preferredWorkoutType WorkoutType?\n  createdAt            DateTime           @default(now())\n  updatedAt            DateTime           @updatedAt\n}\n\nenum WorkoutStatus {\n  PLANNED\n  COMPLETED\n}\n\n// Reuses WorkoutType from the Fitness Profile taxonomy (Step 1) rather than\n// defining a second one, per the requirement to align the two. workoutType\n// is nullable — a workout doesn't strictly need a category to be useful.\n// status only ever moves PLANNED -> COMPLETED via PATCH /:id/complete;\n// title/description/scheduledDate/durationMinutes/workoutType are edited\n// via PUT — keeping \"mark complete\" as the single path that can set\n// COMPLETED avoids two different endpoints being able to race on the same\n// transition.\nmodel Workout {\n  id              String        @id @default(cuid())\n  userId          String\n  user            User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  title           String\n  workoutType     WorkoutType?\n  description     String?\n  scheduledDate   DateTime?\n  durationMinutes Int?\n  status          WorkoutStatus @default(PLANNED)\n  completedAt     DateTime?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  @@index([userId])\n  @@index([userId, scheduledDate])\n}\n\nenum MealType {\n  BREAKFAST\n  LUNCH\n  DINNER\n  SNACK\n}\n\n// foodName/mealType/servingSize/calories/consumedAt are required; the three\n// macro fields are optional (nullable) — logging a food's calories without\n// full macro detail is a normal, lighter-weight use case, same philosophy\n// as Profile's optional fields in Step 1. Macros use Decimal (not Float) so\n// daily-total aggregation happens as exact DECIMAL arithmetic in Postgres\n// (via Prisma's aggregate/_sum), not floating-point summation in JS.\nmodel NutritionEntry {\n  id                 String   @id @default(cuid())\n  userId             String\n  user               User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  foodName           String\n  mealType           MealType\n  servingSize        String\n  calories           Int\n  proteinGrams       Decimal?\n  carbohydratesGrams Decimal?\n  fatGrams           Decimal?\n  consumedAt         DateTime\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n\n  @@index([userId])\n  @@index([userId, consumedAt])\n}\n\n// weight is required (it's the entry's primary purpose); measurements and\n// bodyFatPercent are all nullable — same \"optional detail, required core\"\n// philosophy as Profile (Step 1) and Nutrition (Step 3). Decimal is used\n// throughout for the same reason as Nutrition's macros: exact numeric\n// storage, no floating-point drift.\nmodel Progress {\n  id             String   @id @default(cuid())\n  userId         String\n  user           User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  recordedAt     DateTime\n  weight         Decimal\n  chest          Decimal?\n  waist          Decimal?\n  hips           Decimal?\n  arms           Decimal?\n  thighs         Decimal?\n  bodyFatPercent Decimal?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  photos ProgressPhoto[]\n\n  @@index([userId])\n  @@index([userId, recordedAt])\n}\n\n// No userId here — ownership is derived transitively through\n// progress.userId. Every read/write is scoped by a `progress: { userId }`\n// relation filter in the query itself, not a separate check-then-act step.\n// Stores a URL/path only, never binary image data — the MVP representation\n// the blueprint specifies, ready to point at S3 once that's built (later\n// phase, explicitly out of scope here).\nmodel ProgressPhoto {\n  id         String   @id @default(cuid())\n  progressId String\n  progress   Progress @relation(fields: [progressId], references: [id], onDelete: Cascade)\n  url        String\n  createdAt  DateTime @default(now())\n\n  @@index([progressId])\n}\n",
